import{_ as l,o as a,c as r,aA as i}from"./chunks/framework.BMzE2Z9R.js";const t="/assets/%E7%8E%8B%E5%9F%B9%E8%80%81%E5%B8%88%E7%9B%B8%E7%89%87.C5mTVBpa.png",m=JSON.parse('{"title":"研究团队介绍","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"about/team.md","filePath":"about/team.md","lastUpdated":1778399398000}'),o={name:"about/team.md"};function p(n,e,h,u,s,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="研究团队介绍" tabindex="-1">研究团队介绍 <a class="header-anchor" href="#研究团队介绍" aria-label="Permalink to &quot;研究团队介绍&quot;">​</a></h1><h2 id="王培" tabindex="-1">王培 <a class="header-anchor" href="#王培" aria-label="Permalink to &quot;王培&quot;">​</a></h2><blockquote><p>美国天普大学计算机系教授，博士生导师。博士师从侯世达（Douglas Hofstadter）。</p></blockquote><p><img src="'+t+'" alt="王培老师相片"></p><p><a href="https://cis.temple.edu/~pwang/" target="_blank" rel="noreferrer">学术主页↗</a><a href="https://cis.temple.edu/~pwang/PeiWangCV.html" title="Curriculum Vitae of Pei Wang (temple.edu)" target="_blank" rel="noreferrer">个人CV↗</a><a href="https://chn.oversea.cnki.net/kcms/detail/knetsearch.aspx?sfield=au&amp;skey=%E7%8E%8B%E5%9F%B9&amp;code=000030813766&amp;v=S9YHj3BEsKa5fwwTFPnTmqScyLd2I_AasnZGijQCwpKf4UHLVXsBbaUm89ugcmww" target="_blank" rel="noreferrer">知网↗</a><a href="mailto:pei.wang@temple.edu" target="_blank" rel="noreferrer">email↗</a></p><p>主要研究:</p><ul><li>通用人工智能</li><li>非公理推理</li><li>逻辑与推理</li><li>不确定性</li><li>意义与真值</li><li>概念与学习</li><li>动态资源管理</li></ul><p>王培教授是</p><ol><li>OpenNARS项目（通用人工智能项目）的发起人和主要编写者，</li><li><a href="http://agi-conf.org/" target="_blank" rel="noreferrer">国际AGI协会</a>的发起人和常驻委员</li><li>《哥德尔、埃舍尔、巴赫——集异璧之大成》的译者之一</li></ol><p>同时也是</p><ol><li>中国NARS小组的指导老师</li><li>中国通用人工智能协会的常驻点评指导老师</li></ol><p>关于王培教授的头衔和周边，实在太多，建议点击下面的链接，观看视频，阅读论文和项目源码，了解详情：</p><ul><li><a href="https://cis.temple.edu/~pwang/Chinese.html" target="_blank" rel="noreferrer">中文资料</a></li><li><a href="https://github.com/opennars/opennars/wiki" target="_blank" rel="noreferrer">OpenNARS Wiki</a></li><li><a href="http://www.dushuren123.com/dushuren/video/share.html?id=1679351024" target="_blank" rel="noreferrer">读书人《通用人工智能》讲座视频</a></li><li><a href="http://agi-conf.org/" target="_blank" rel="noreferrer">国际AGI协会官网</a></li></ul><h3 id="个人访谈" tabindex="-1">个人访谈 <a class="header-anchor" href="#个人访谈" aria-label="Permalink to &quot;个人访谈&quot;">​</a></h3><p><a href="https://cis.temple.edu/~wangp/interviews.html" target="_blank" rel="noreferrer">Pei Wang Interviews (temple.edu)</a></p><p>里面有一些关于个人问题的回答等。与AGI强相关。</p><h2 id="刘凯" tabindex="-1">刘凯 <a class="header-anchor" href="#刘凯" aria-label="Permalink to &quot;刘凯&quot;">​</a></h2><blockquote><p>博士，渤海大学，教育科学学院，教育技术学学硕及心理健康教育专硕硕士生导师，中国通用人工智能协会（筹）召集人</p></blockquote><p><a href="https://www.zhihu.com/people/wuyuezhidian" target="_blank" rel="noreferrer">知乎↗</a><a href="https://space.bilibili.com/475410405" target="_blank" rel="noreferrer">Bilibili↗</a><a href="https://www.youku.com/profile/index/?uid=UMjE3MDM1OTcy" target="_blank" rel="noreferrer">优酷↗</a><a href="https://chn.oversea.cnki.net/kcms/detail/knetsearch.aspx?sfield=au&amp;skey=%E5%88%98%E5%87%AF&amp;code=000047659669;000047659669&amp;v=y7vj98LMVg_UHxhubKBjMQQpbklWyJGk5a_8PeXYFeCYzWi5m1uTEUjjoX1xjAIIOeb1sc-Ug9eznEYpNQXXLA==" target="_blank" rel="noreferrer">知网↗</a></p><p>研究方向：</p><ul><li>通用人工智能与教育大科学的理论与实践</li><li>类脑系统开发与机器教育</li><li>计算精神病学</li></ul><p>研究层次：</p><ol><li>理论 <ol><li>一般智能理论</li><li>一般学习理论</li><li>一般教育理论（含职业教育）研究</li></ol></li><li>技术 <ol><li>基于理解的动态学科知识图谱构建（学科数学）</li><li>教学材料的自组织与自改进（教育技术学）</li><li>精神障碍心理学标记物的拓扑发现与定位（精神病学）</li><li>基于经验建构的机器婴儿主动视觉（计算机科学）</li></ol></li><li>工程 <ol><li>研发通用人工智能框架下的类脑系统（计算机科学）</li></ol></li><li>应用 <ol><li>基于认知建构的下一代ITS（教育技术学）</li><li>教育干预手段治疗精神障碍（精神病学）</li></ol></li></ol><h2 id="徐英瑾" tabindex="-1">徐英瑾 <a class="header-anchor" href="#徐英瑾" aria-label="Permalink to &quot;徐英瑾&quot;">​</a></h2><blockquote><p>哲学博士，复旦大学哲学学院教授，博士生导师</p></blockquote><p><a href="https://philosophy.fudan.edu.cn/64/8f/c14253a222351/page.htm" target="_blank" rel="noreferrer">学术主页↗</a><a href="https://baike.baidu.com/item/%E5%BE%90%E8%8B%B1%E7%91%BE/1778275" target="_blank" rel="noreferrer">百度百科↗</a><a href="https://space.bilibili.com/1030" target="_blank" rel="noreferrer">Bilibili↗</a><a href="https://chn.oversea.cnki.net/kcms/detail/knetsearch.aspx?sfield=au&amp;skey=%E5%BE%90%E8%8B%B1%E7%91%BE&amp;code=000036949310&amp;v=f5P6chuNTza-7Rk3TFVHPGmsJDI8Q8tRORf9XlH8k8njXtviqPM535RNdHPUPx1o" target="_blank" rel="noreferrer">知网↗</a><a href="mailto:yjxu@fudan.edu.cn" target="_blank" rel="noreferrer">email↗</a></p><p>专长：</p><ul><li>分析哲学史</li><li>心灵哲学</li><li>人工智能哲学</li><li>分析哲学与欧陆哲学比较研究</li></ul><p>著作：</p><ul><li>《人工智能哲学十五讲》</li><li>《心智、语言和机器——维特根斯坦哲学与人工智能哲学的对话》</li></ul><p>现为复旦大学哲学学院教授、博士生导师、全国重大社科项目“基于信息技术哲学的当代认识论研究”首席专家。</p><p>曾在意大利与美国各自进修一年。</p><p>他在这五年中（以及稍早的一些时候）累计获得</p><ul><li>两次上海市哲学社会科学优秀成果奖（一、二、三等奖各一次）</li><li>两次全国高等院校优秀人文社会科学成果奖（二等奖，2009年；二等奖，2015）。</li></ul><p>在2009年他被上海市委宣传部下属的东方学社评为“上海十大社科新人”，这是当年上海哲学界唯一入选者。</p><p>同时，他至今依然是上海哲学界目前唯一的全国优秀博士论文的获得者（2006年获奖）。</p><ul><li>获奖的论文《维特根斯坦哲学转型期中的“现象学”之谜》（2006年复旦大学出版社出版，28万字）是汉语哲学界第一部（至今也是唯一一部）专门讨论维特根斯坦从其早期立场转向晚期立场之转型过程的专著。</li></ul><p>代表作《心智、语言和机器——维特根斯坦哲学与人工智能哲学的对话》（76万字，人民出版社2013年10月出版）是国内目前最全面深入的关于人工智能哲学的研究著作。</p><p>目前徐英瑾还任中国知识论专业委员会副秘书长，2018年担任“世界哲学大会”人工智能分会场主席。</p><p>（上述资料源自学术主页）</p><h2 id="那孜古力·斯拉木-那迪" tabindex="-1">那孜古力·斯拉木(那迪) <a class="header-anchor" href="#那孜古力·斯拉木-那迪" aria-label="Permalink to &quot;那孜古力·斯拉木(那迪)&quot;">​</a></h2><blockquote><p>博士，西北民族大学，中国民族信息技术研究院，计算机技术、人工智能、大数据方向的硕士研究生导师</p></blockquote><p><a href="https://chn.oversea.cnki.net/kcms2/author/detail?v=wRD08hUPYgwHqv6pqt1Lry077C8HmYeFUg_u_vKAKELr9EuNyzuelYm8aFEHWLCDlsaQ35mKa0ssz5y7seHPRwYweIqJYvLqGRxektNLWL-gjim3eRBvXXRWBg--mAzQraqInCBc1Zy03vfEnEBPhEIi3C0Kz5X0byKD64Kg2olxmlgOimKHfRjBS1efeJAW&amp;uniplatform=NZKPT&amp;language=CHS" target="_blank" rel="noreferrer">知网↗</a></p><p>主要研究领域：</p><ol><li>智能决策</li><li>数据科学</li><li>通用人工智能理论与技术</li></ol><p>个人履历：</p><ul><li>2005年毕业于新疆大学信息科学与工程学院并获计算机科学与技术专业工学学士学位</li><li>2008年毕业于新疆大学信息科学与工程学院并获计算机应用技术专业工学硕士学位</li><li>2016年毕业于天津大学计算机科学与技术学院并获计算机应用技术专业博士学位</li></ul><p>中国计算机学会专业会员。</p><p>在SCI期刊、EI检索会议和国内核心期刊发表论多篇论文；</p><p>作为项目负责人获得新疆维吾尔自治区自然科学面向基金、国家博士后基金、西北民族大学人才引进项目启动基金等三项基金资助。</p><h2 id="魏屹东" tabindex="-1">魏屹东 <a class="header-anchor" href="#魏屹东" aria-label="Permalink to &quot;魏屹东&quot;">​</a></h2><blockquote><p>博士，山西大学教授，哲学方向博士生导师</p></blockquote><p><a href="https://cap.sxu.edu.cn/yjry/2358.htm" target="_blank" rel="noreferrer">学术主页↗</a><a href="https://chn.oversea.cnki.net/kcms2/author/detail?v=wRD08hUPYgym68S7GHd2poHMO-BDlA-GdxcWHe-R3H4JseLdQZ2VugdAtBPQIQnqVd2rPnJWpGXF8IQ_BKdhrwZnUrFnLUSwvC8RPbBMj0E_1-ZNNWcNYYVZ8VQ8TSPD&amp;uniplatform=NZKPT&amp;language=CHS" target="_blank" rel="noreferrer">知网↗</a></p><p>主要研究领域：</p><ul><li>适应性表征</li><li>自然科学理论与方法</li><li>哲学</li><li>心理学</li></ul><h2 id="李祥" tabindex="-1">李祥 <a class="header-anchor" href="#李祥" aria-label="Permalink to &quot;李祥&quot;">​</a></h2><blockquote><p>博士，辽宁工业大学计算机讲师，人工智能方向硕士生导师。博士师从<a href="#_1">王培</a></p></blockquote><p><a href="https://seie.lnut.edu.cn/info/14393/185134.htm" target="_blank" rel="noreferrer">学术主页↗</a><a href="mailto:xiangliagi@lnut.edu.cn" target="_blank" rel="noreferrer">email↗</a><a href="tel:+86-0416-4198700" target="_blank" rel="noreferrer">联系电话↗</a></p><p>主要研究领域：</p><ol><li>通用人工智能</li><li>认知科学</li><li>人工智能情感</li></ol><p>主讲：</p><ul><li>本科生课程 <ul><li>分布式数据库</li><li>分布式大数据处理技术</li><li>数据结构</li><li>算法与程序设计</li></ul></li><li>研究生课程 <ul><li>人工智能</li><li>机器学习</li></ul></li></ul><p>主持科研项目：</p><ul><li>辽宁省教育厅面上项目：情感在实现自主化通用人工智能中的作用与机制</li><li>辽宁工业大学博士启动项目： 通用人工智能中自我意识以及情感的研究</li></ul>',64)])])}const d=l(o,[["render",p]]);export{m as __pageData,d as default};
